            return np.r_[np.c_[L,(U[:n,:,None]*(V[:n]@h)[:,None,:]).reshape(n,-1),(V[:n,:,None]*(U[:n]@a)[:,None,:]).reshape(n,-1)],np.c_[np.zeros((2*d*rank,9)),pen*np.eye(2*d*rank)]]
